insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 1, 1, $json${"week":1,"day":1,"title":"The forest road","heading":"The old forest road","question":"who is this man, and what does he want with me?","steps":[{"t":"say","text":"The wagon axle snaps on the old forest road, and something is already moving in the treeline.\n\nA man steps out with a blade drawn. He does not ask for your purse. He does not say anything at all."},{"t":"fight","name":"A MAN ON THE ROAD","desc":"He means it. So must you.","firstLines":null,"strikeFirst":{"on":"player"}},{"t":"say","text":"He breaks off. One look at you, and he is gone into the trees before you can lay a hand on him.","cond":{"on":"fight","won":true}},{"t":"say","text":"You are on your back in the road. He could finish it. He looks down at you for a long moment, and then he is gone into the trees.","cond":{"on":"fight","won":false}},{"t":"say","text":"The road is very quiet."},{"t":"choice","id":0,"labels":["LOOK WHERE HE STOOD","LOOK AT WHAT HE WAS AT"],"mode":"each","branches":[{"options":[0],"text":"A scrap of parchment in the leaf-mould, half burned. It is not writing and it is not a drawing. Somebody laid it over something hard and raised, and rubbed charcoal across it until the shape came through.\n\nYou do not know the shape."},{"options":[1],"text":"Your cargo box. The lock is jammed, and the scratches round it are fresh. They are not yours.\n\nHe was at this before you ever saw him."}]},{"t":"notice","lines":{"Might":{"first":"He held back. Every blow came a half-beat late."},"Craft":{"first":"The lock was not forced open. It was forced shut."},"Intellect":{"first":"A robber goes for the purse and the horse. He went for neither."},"Charm":{"first":"He never once looked angry. He looked like a man doing a job."},"Agility":{"first":"He was in the trees before your axle went. He was waiting for it."},"Aim":{"first":"That axle did not snap. It was cut most of the way through."}}},{"t":"challenge","title":"OPEN THE BOX","desc":"You need to know what he wanted in here, and the light is going on a road he knows better than you do.","options":[{"attr":"Might","verb":"force it"},{"attr":"Craft","verb":"work the jammed mechanism free"}],"reward":"+500g","fail":"it costs you skin and most of an hour of daylight"},{"t":"say","text":"It gives at the first try.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It gives in the end. Your knuckles are bleeding and the trees have gone from green to black.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"You go through the box twice. Everything you own is here. Nothing has been taken.\n\nSomething has been put in.\n\nA second scrap, clean and unburned: a list, in a neat, steady hand. **{N} names. Yours is one of them.** Under them a single line that is not a name.\n\n**The Hollow Wake Inn, on the drove road.**"},{"t":"say","text":"Where your road meets the drove road an old boundary stone stands half-buried in the verge, weathered past reading. Something in a crack at its foot catches the last of the light."},{"t":"act","label":"PULL IT OUT"},{"t":"say","text":"Thin, dense, and cold in a way nothing should be at this time of year. It is not paper. It has not aged the way paper would.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"A man broke into your box to leave you a list with your name on it.\n\n**One day north: the Hollow Wake Inn. Somebody wants you there.**","pull":true},{"t":"summary","lines":["**THE FOREST ROAD** · Day 1","You earned: `[gold]` · your class Attribute `[growth]`","You learned: nothing was taken. A list of {N} names was left for you, and the name of an inn.","You hold: the list · a half-burned charcoal rubbing","Fragment: 1 found, locked","Tomorrow: **the Hollow Wake Inn, a day north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 2, $json${"week":1,"day":2,"title":"The Hollow Wake Inn","heading":"The Hollow Wake Inn","question":"who are the others on the list, and who wrote it?","steps":[{"t":"say","text":"The taproom is warm and low and smells of woodsmoke. There are {N-1} strangers in it who are not drinking.\n\n{F1} has a torn page flat on the table under one hand. {F2} is turning one over and over. {F3}'s is folded small, the way you fold a thing you have read too many times.\n\nYou put yours down beside them. The same neat hand. The same names, each with a date beside it.\n\nNobody has to explain."},{"t":"say","text":"The innkeeper sets down the cups. He sets down one more than there are of you, at the empty end of the table, and goes back behind his bar."},{"t":"act","label":"ASK HIM ABOUT THE LIST"},{"t":"say","text":"He looks at the pages for a while. Then he reaches under the bar and brings out a satchel, worn soft at the corners.\n\n*\"Woman called Meira. Scholar. Sat right there most nights, two years near enough. Cheapest wine in the house, and tipped like a queen.\"*\n\nHe puts it on the table.\n\n*\"Left this. Hasn't been back in three weeks.\"*"},{"t":"say","text":"Inside is a notebook, packed to the margins in the hand you all know by now. Your names are in it. Every one of you.\n\n{STAKE}\n\nAnd near the back, where the binding shows, some pages are gone."},{"t":"notice","lines":{"Might":{"first":"The satchel strap has been mended three times.","second":"She carried this a long way, often."},"Agility":{"first":"{F2}'s knuckles are skinned. So are {F3}'s.","second":"Every one of you fought somebody to get here."},"Intellect":{"first":"The notes are in two inks.","second":"She came back to these pages years apart."},"Charm":{"first":"The innkeeper has not asked a single one of you your name."},"Craft":{"first":"The binding thread is cut, not torn.","second":"Whoever took those pages took care."},"Aim":{"first":"There is one seat in this room that sees both doors.","second":"It is the one he says was hers."}}},{"t":"challenge","title":"FIT THE PAGE","desc":"Your page came out of this book. Prove it, and find what else is on the leaf it came from.","options":[{"attr":"Intellect","verb":"match the hand, line by line, to the entries on either side"},{"attr":"Craft","verb":"match the torn edge to its stub, fibre to fibre"}],"reward":"+500g","fail":"it takes you the whole evening, with strangers watching you get it wrong"},{"t":"say","text":"Your stub fits like a key. There are {N} stubs, and {N} of you.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You try it against every stub but the right one. {F1}, in the end, reaches over and turns your page the other way up. It fits. There are {N} stubs, and {N} of you.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"READ THE STUBS","detail":"what is left on the torn edges themselves","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Each stub has a faint straight line scored down it. She did not rip these out. She cut them against a rule, one at a time, with care.\n\nShe meant to send them.","cond":{"on":"press"}},{"t":"say","text":"So the list is hers. She wrote your names in a book, and cut them out, and then she stopped coming here. And each of you was set upon on the road, within the same few days, and came away holding a page."},{"t":"say","text":"On the facing leaf, one line will not be read at all. It is in some private shorthand, tight as wire."},{"t":"act","label":"ASK HIM ABOUT THE LINE NOBODY CAN READ"},{"t":"say","text":"He does not look up from the bar.\n\n*\"That's a rock. Split lightning-wise, about so high. Two hours north.\"*\n\nHe goes on wiping.\n\n*\"She'd sit right there. I doubt she thought I was listening.\"*"},{"t":"say","text":"With the place put to it, the rest of the page can be read, and it names none of you.\n\nIt is about a child. Taken, and held somewhere near that rock. No date. Only the place, and the plain sense, in every line of it, that whatever was happening there was not over."},{"t":"act","label":"ASK HIM TO TAKE YOU THERE"},{"t":"say","text":"He sets down the glass.\n\n*\"I've a business to run.\"*"},{"t":"act","label":"TELL HIM NOBODY ELSE CAN READ HER"},{"t":"say","text":"A long pause. He looks at the satchel, and the pages, and each of you in turn.\n\n*\"...As far as the Widow's Tooth. That's all I'm agreeing to.\"*"},{"t":"say","text":"You pay before you go up. {F2} puts down more than the cups were worth and nobody counts it. The innkeeper sweeps the coins into his apron without a word.\n\nThe extra cup is still at the empty end of the table. Nobody has touched it."},{"t":"say","text":"By the door, an old verse is carved into the beam, so old the wood has grown round the letters. Under it somebody has worked a small hollow into the timber."},{"t":"act","label":"FEEL INSIDE"},{"t":"say","text":"Cold enough to feel through the warm wood.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Upstairs, by a candle, you turn the notebook's last pages. Two lines in her hand, written years apart, in different inks:\n\n*\"Scattered on purpose, each piece safe alone. Only together do they mean anything.\"*\n\n*\"The old tellings of the Seekers speak of stones. The oldest records don't call them stones at all. They call them shards.\"*\n\nYou do not know what she meant."},{"t":"say","text":"**First light. Two hours north. A child was held at that rock, and whatever it is has not finished.**","pull":true},{"t":"summary","lines":["**THE HOLLOW WAKE INN** · Day 2","You earned: `[gold]` · Intellect or Craft `[growth]`","You learned: the list is **Meira's**. She has been missing three weeks. Her last readable page is about a child held near a rock called the Widow's Tooth.","You hold: Meira's satchel and notebook","Fragment: 2 found","Tomorrow: **the Widow's Tooth, two hours north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 1, 3, $json${"week":1,"day":3,"title":"The Widow's Tooth","heading":"The Widow's Tooth","question":"is the child still at the rock?","steps":[{"t":"say","text":"Two hours north the road runs straight at a rock taller than a house, split down the middle as if something struck it once, long ago.\n\nIt is the first time the {N} of you have walked anywhere together. The innkeeper has already complained about the road, his boots and the weather, in that order, and seems to be enjoying himself.\n\nSomebody must have asked him how he knew this place from a line of scribble, because he answers it to the air.\n\n*\"People tell a man with a cloth in his hand everything,\"* Garrick says. *\"They forget he's got ears.\"*"},{"t":"say","text":"There is nobody at the rock.\n\nThere are tracks at its foot: several people, not long ago, and a cart. And low on the stone, half worn away, something has been cut into it."},{"t":"choice","id":0,"labels":["GO TO THE MARKING","FOLLOW THE CART-RUTS"],"mode":"pick","branches":[{"options":[0],"text":"You crouch at the stone. That is where you are, with your back to the bracken, when the bracken moves."},{"options":[1],"text":"The ruts turn off the road toward a line of trees, and smoke beyond them. You are looking that way, so you see him first: a man lying flat in the bracken, watching the rock."}]},{"t":"notice","lines":{"Might":{"first":"The ruts are deep going in and shallow coming out.","second":"The cart left lighter than it came. Or it left something here."},"Agility":{"first":"The bracken is flattened in one place only.","second":"He has been lying there since before dawn."},"Intellect":{"first":"Nobody watches an empty rock.","second":"So it is not empty to him, or it will not be for long."},"Charm":{"first":"He is not afraid of you. He is afraid of being seen by you."},"Craft":{"first":"The cart has one wheel that pulls left.","second":"You would know its track again."},"Aim":{"first":"From where he lies he can see the road both ways and the village smoke.","second":"It is a post, and it has been used before."}}},{"t":"fight","name":"THE MAN IN THE BRACKEN","desc":"He comes up running, and he is not running away.","firstLines":["You saw him first: you strike before he is set.","He was behind you: he strikes first."],"strikeFirst":{"on":"choice","choice":0,"options":[1]}},{"t":"say","text":"He does not say a word. Not when he is hit, and not when he hits. The moment there is a gap he takes it, and he is away through the trees toward the smoke, faster than any of you.\n\n{F3} goes twenty yards after him and stops."},{"t":"say","text":"You had him by the collar for a moment, close enough to smell him. Woodsmoke, and lamp oil.","cond":{"on":"fight","won":true}},{"t":"say","text":"You go back to the rock.\n\nSomebody takes the burned scrap from the forest road out of a pocket, and holds it against the marking.\n\nIt fits. Every raised line sits under its line of charcoal, and there is charcoal still, ground into the edges of the stone. She laid her paper here and rubbed. This rock is what the scrap is a picture of.\n\nMeira stood where you are standing. And the man who came at you on the forest road was carrying her work."},{"t":"say","text":"Under the overhang, on a dry shelf out of the wind, something small is lying on its side."},{"t":"act","label":"PICK IT UP"},{"t":"say","text":"A carved horse, no longer than your thumb. It is grey with a winter or two of weather.\n\nIt is a child's. It has been here a long time."},{"t":"say","text":"There is a crack in the stone under the marking, wide enough for a hand."},{"t":"act","label":"REACH IN"},{"t":"say","text":"The same cold. The same weight.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Garrick has not gone back to his inn. He is standing in the road with his pack on, looking at the smoke.\n\n**The ruts go that way. So did the man. He will be there before you, and every door will be shut when you come.**","pull":true},{"t":"summary","lines":["**THE WIDOW'S TOOTH** · Day 3","You earned: `[gold]`","You learned: nobody is here. But **Meira made her rubbing at this rock**, and a child was kept here once.","You hold: a small carved horse","Fragment: 3 found","Tomorrow: **Fenmark, where the cart went**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 4, $json${"week":1,"day":4,"title":"Fenmark","heading":"Fenmark, where the cart went","question":"what happened in this village, and why will nobody say?","steps":[{"t":"say","text":"Fenmark goes quiet the moment you come down the lane. Doors do not quite shut. Nobody is standing in one, either.\n\nThe lookout from the rock came through here ahead of you. You can tell by the gate at the far end of the street, left swinging.\n\n{F1} takes the left side of the lane, {F2} the right. You take the well."},{"t":"say","text":"Behind the well, on an upturned bucket: a bowl of barley, half eaten. You hold your hand over it. It is still warm.\n\nWhoever was eating it left in a hurry, and not long ago."},{"t":"notice","lines":{"Might":{"first":"The bucket was not knocked over. It was set down.","second":"Whoever sat here is small, and careful."},"Agility":{"first":"One heel-mark in the mud, deep at the toe. They went at a run.","second":"Toward the back lanes, not the road."},"Intellect":{"first":"Barley and nothing else, in a house bowl. This is somebody's ordinary dinner.","second":"They live here, and they did not expect to be found."},"Charm":{"first":"Every shutter on the street is closed but one.","second":"Somebody wants to be asked."},"Craft":{"first":"The spoon is whittled, not bought, and whittled badly.","second":"A child's knife did that."},"Aim":{"first":"From this bucket you can see the whole lane and nobody in the lane can see you.","second":"It was chosen for watching."}}},{"t":"choice","id":0,"labels":["LOOK FOR FOOTPRINTS","KNOCK NEXT DOOR"],"mode":"flavor","branches":[]},{"t":"challenge","title":"FIND WHO LEFT IT","desc":"Somebody in this village watched something, and is hiding from you. Find them before the whole street knows you are looking.","options":[{"attr":"Agility","verb":"follow the fresh prints round the back lanes"},{"attr":"Charm","verb":"coax the neighbour at her half-open door into pointing"}],"reward":"+500g","fail":"you search the wrong end of the village first, in full view"},{"t":"say","text":"The prints are small and quick, and they double back twice. You do not follow them. You walk round the grain store the other way and sit down on the step.\n\nAfter a while a boy of about fourteen edges out of the gap behind it. He has seen you see him. He does not run.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You try three doors on the wrong side of the street, and three faces watch you do it. By the time you think of the grain store the boy has bolted from behind it, straight into {F3}, who was coming the other way.\n\nHe is shaking. {F3} lets go of his sleeve and steps back.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"He looks at each of you in turn. He is counting you."},{"t":"choice","id":1,"labels":["SHOW HIM THE LIST","ASK WHO WAS TAKEN","SAY NOTHING. WAIT."],"mode":"flavor","branches":[]},{"t":"say","text":"It comes out low and fast.\n\n*\"Three nights ago. They came in the dark with no torches. They did not knock anything over. They did not say anything they did not have to. Like they'd done it before.\"*\n\n*\"They took Tamsin. She's nine. She was counting when they carried her out. She counts when she's frightened.\"*\n\nHe swallows.\n\n*\"One of them had a knife I'd never seen the like of. Curved. Black handle. He saw me at the window. He did not even walk faster. He just said they'd know if I talked.\"*"},{"t":"say","text":"While he talks he hums, without noticing, a rhyme with no tune to speak of. His grandmother's, he says. She sang it here, at the well.\n\nYou look at the well. Its stone lip is older than every house in the street, and worn into it, just where a hand would rest, is a hollow."},{"t":"act","label":"REACH IN"},{"t":"say","text":"Your fingers close on something thin and cold. Well-water beads on it and will not soak in.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"Boots on the cobbles.\n\nAn old man is coming down the street with two younger ones behind him, and the two younger ones walk straight past him and stand between you and the well."},{"t":"say","text":"The boy is still standing next to you. He does not move away.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"The boy is behind {F3}. One of the men looks at him, and he looks at the ground.","cond":{"on":"challenge","pass":false}},{"t":"choice","id":2,"labels":["STAND WHERE YOU ARE","STEP BACK, HANDS OPEN","PUT YOURSELF IN FRONT OF THE BOY"],"mode":"flavor","branches":[]},{"t":"say","text":"Nobody draws. Nobody needs to. It is a very clear message.\n\nThe elder says the things an elder says: that Fenmark has no quarrel with travellers, that the road out is the same as the road in.\n\nBut you are watching his hands, and his hands are not angry. They are afraid. He is not hiding what happened here. He is terrified of what happens to this village if it is known that somebody talked.\n\nHe steps in close, as if to see you off. His voice drops until only you can hear it.\n\n*\"Please. There's a woman two hours east who's seen that same curved blade before. Ask her. Don't say I sent you.\"*\n\nThen, louder, for the street: *\"Go on, now.\"*"},{"t":"say","text":"Garrick is already holding the gate at the bottom of the lane. He has found the one dry place to stand in all of Fenmark, and he looks as if he would like you to notice.\n\nThe boy catches up with you there, out of breath.\n\n*\"A man ran through at first light. He did not stop for anyone. He took the east path.\"*"},{"t":"say","text":"**East. Two hours. He has half a day on you, and he is heading for the only other person alive who has seen that knife.**","pull":true},{"t":"summary","lines":["**FENMARK** · Day 4","You earned: **+500g** · **Charm 14 → 26** · *Apprentice reached: +2 on every Charm roll*","You can now afford: an Attribute Relic · *450g more for Weapon Lv. 2*","You learned: her name is **Tamsin**. Nine years old. Taken three nights ago by quiet men; one carries a curved, black-handled knife.","Fragments: 4 found","Tomorrow: **the old charcoal camp, two hours east**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 1, 5, $json${"week":1,"day":5,"title":"The old charcoal camp","heading":"East, to the charcoal camp","question":"who has seen the curved knife, and what happened that time?","steps":[{"t":"say","text":"The camp is an old one: burning-pits long cold, a trade that left years ago. But the path in is worn too clean for that to be all of it.\n\nAt the edge of the clearing is a shed. You get there after dark. Nobody answers."},{"t":"choice","id":0,"labels":["LOOK AT THE STEP","LOOK AT THE FIRE","LOOK AT THE PATH"],"mode":"pick","branches":[{"options":[0],"text":"Swept this morning. Somebody lives here, and is proud enough to sweep."},{"options":[1],"text":"Cold on top. Warm underneath, when you push a hand in. Banked, not dead. Somebody means to come back to it."},{"options":[2],"text":"Two sets of prints on it, both fresh. A woman's, going out. And over them a man's, coming in, at a run.\n\nHe is here."}]},{"t":"notice","lines":{"Might":{"first":"The axe is gone from the block. The block is still wet.","second":"Whoever lives here took it with them, and not for wood."},"Agility":{"first":"A shed with one door and a shuttered back window.","second":"Somebody inside it could be gone before you knocked twice."},"Intellect":{"first":"Nobody keeps a place this tidy and this hidden unless they are waiting for something."},"Charm":{"first":"There is one bowl, one cup, one stool.","second":"She has been alone a long time."},"Craft":{"first":"The shutters bar from the inside and the outside both.","second":"She built this to be watched from."},"Aim":{"first":"There is a gap in the trees that frames the whole clearing.","second":"You are being looked at through it now."}}},{"t":"say","text":"Something moves behind the shed."},{"t":"fight","name":"THE RUNNER FROM FENMARK","desc":"He got here first. He is trying the shutters.","firstLines":["You read the path: you are ready for him.","He hears you before you see him."],"strikeFirst":{"on":"choice","choice":0,"options":[2]}},{"t":"say","text":"The same silence. The same way of leaving: the first gap, and gone, north through the trees this time.\n\n{F1} has a hand on {F2}'s arm, to stop {F2} following into the dark."},{"t":"say","text":"He has left his knife behind, stuck in the shutter where he was working it. A plain kitchen knife. There is nothing curved about it.","cond":{"on":"fight","won":true}},{"t":"say","text":"A twig goes.\n\nShe is at the edge of your firelight, and she has been there for some time. A woman with a woodcutter's axe held low and ready, and her eyes going from face to face.\n\n*\"Which of you carries the curved knife?\"*"},{"t":"choice","id":1,"labels":["SHOW HER YOUR EMPTY HANDS","TELL HER WHO YOU JUST DROVE OFF","HOLD OUT THE CARVED HORSE"],"mode":"pick","branches":[{"options":[0,1],"text":"The axe comes down by inches. Then her eyes go to the carved horse in your other hand, and stop."},{"options":[2],"text":"The axe comes down all at once."}]},{"t":"say","text":"She takes the little horse in both hands. She has to sit.\n\nGarrick builds the fire up without being asked, and puts a cup into her hands. She holds it as if it were the first warm thing she has touched in a month.\n\n*\"That's my sister's boy's,\"* she says. *\"I carved it.\"*"},{"t":"say","text":"It comes out fast and low.\n\n*\"Curved. Black-handled. I know it. Same man took him two winters back. Same time of year. Same stretch of country. Nobody ever found him.\"*\n\nShe turns the horse over.\n\n*\"Where was it?\"*\n\nYou tell her. She nods, slowly, as if she had always known the rock."},{"t":"say","text":"You count it out, because somebody has to.\n\nMeira has been gone three weeks. Tamsin was taken this week. The child in Meira's notes, held near the rock, cannot be Tamsin.\n\nMeira was writing about this woman's nephew. About the last one.\n\nAnd it is the same time of year."},{"t":"say","text":"She says a thing twice while she talks, hardly hearing herself: *\"The power that gives is also the power that takes.\"* She cannot say where she first heard it. Her eyes go, when she says it, to the old dead tree behind the shed, hollow at the foot."},{"t":"act","label":"REACH INTO THE HOLLOW"},{"t":"say","text":"Wrapped in something long since rotted to threads. Still cold.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"At first light she walks you to the edge of the camp, and stands on the old charcoal road, and points.\n\n**North. The same man, the same country, the same season. If it comes round like a calendar, the time is now.**","pull":true},{"t":"summary","lines":["**THE OLD CHARCOAL CAMP** · Day 5","You earned: `[gold]`","You learned: **it has happened before.** The same man took a boy from this country two winters ago, at this time of year. He is the child in Meira's notes.","Fragment: 5 found","Tomorrow: **the ford, on the old charcoal road north**"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 1, 6, $json${"week":1,"day":6,"title":"The ford","heading":"North, to the ford","question":"where did they take her?","steps":[{"t":"say","text":"By midday the old charcoal road comes down to a river. It is shallow enough to wade. A worn stone stands at the edge to show the safe line across.\n\nThe near bank is churned to mud. A cart went over: its ruts come out on the far side and go on.\n\nOne set of prints does not. Small ones. They come down to the water's edge and stop.\n\nThe river is rising. The edge of the mud is going as you watch."},{"t":"notice","lines":{"Might":{"first":"The cart sat low coming down the bank.","second":"It rides high on the far side."},"Agility":{"first":"The small prints are evenly spaced.","second":"Nobody was dragging her. Not yet."},"Intellect":{"first":"A cart that crosses and a child who does not.","second":"They parted here on purpose."},"Charm":{"first":"{F2} has stopped talking. Everybody has."},"Craft":{"first":"The left wheel pulls.","second":"It is the cart from the Widow's Tooth."},"Aim":{"first":"On the far bank, nothing small.","second":"Not one print."}}},{"t":"challenge","title":"READ THE WATERLINE","desc":"The river is taking the prints. Whatever they say, they will say it once.","options":[{"attr":"Aim","verb":"pick out the line of them from the bank before it goes"},{"attr":"Agility","verb":"get down the bank to the water's edge, and read them close before the river takes the rest"}],"reward":"+500g","fail":"the water takes them, and you will never know how she came to it"},{"t":"say","text":"You have them. Small prints, walking, right to the edge. Her own feet. She was not hurt, and she was not carried here.\n\nThen two deep prints facing her, a man's, with the heels dug in. He lifted her. And after that there is only water.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"A brown tongue of river slides over the mud, and when it draws back the mud is smooth. There were prints. Now there is the cart, and nothing.\n\n{F3} finds the last of it, further down: two deep heel-marks, a man's, facing the water. He lifted something. After that there is only water.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"WADE OUT","detail":"find where they went from the water","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Mid-stream, on the upstream side of the ford-stone, a scrape of fresh paint on the rock at the height of a gunwale.\n\nThere was a boat.","cond":{"on":"press"}},{"t":"say","text":"She was carried into the river. The cart went on without her. No tracker alive can follow from here."},{"t":"say","text":"Under the waterline, at the foot of the ford-stone, where you would only see it in a low year:"},{"t":"act","label":"REACH DOWN"},{"t":"say","text":"Cold beyond the cold of the river.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"That is six.\n\nSix of these old scraps in a week, some of them hidden longer than anyone can say, and not one of you has missed one. You have been putting them in your pockets like a child picking up stones.\n\nMeira wrote it: *each piece safe alone. Only together do they mean anything.*"},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"You set them side by side on a flat rock.\n\nThey move.\n\nNot far. The width of a finger. Each one turns a little, and settles against the next, as if they had been waiting for exactly this and exactly these hands. And then they are not six things. They are one.\n\nA map. Old, and exact, in a hand none of you knows.\n\nIt runs across the ford and on. And the place it ends is marked with a shape.\n\n{F1} puts the burned rubbing down beside it.\n\nThe same shape."},{"t":"say","text":"The trail you have lost and the map you are holding point the same way."},{"t":"say","text":"That night you stop at a roadside inn. Garrick orders for the table. When the cups come he pours one more than there are of you, and sets it at the empty place."},{"t":"act","label":"ASK WHO IT IS FOR"},{"t":"say","text":"*\"Family habit. We always pour one for whoever can't be with us.\"*"},{"t":"say","text":"Over supper the way has to be got by heart, and there is only one way to do that."},{"t":"choice","id":0,"labels":["READ IT OUT","LET {F2} READ IT"],"mode":"flavor","branches":[]},{"t":"say","text":"It is read out, twice, slowly, so that everybody has it.\n\nAcross the room a courier who came in for a bed settles his bill without taking one. He is gone within the hour."},{"t":"say","text":"**Cross at first light. You will be there by morning. Whatever is at the place the map marks, the season for it is now.**","pull":true},{"t":"summary","lines":["**THE FORD** · Day 6","You earned: `[gold]` · Aim or Agility `[growth]`","You learned: she was carried into the river and the trail ends. **The six fragments are a map**, and it ends at the mark from Meira's rubbing.","*On a failure:* You missed something at the ford. Someone at the fire may have seen it.","You hold: the map","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · across the ford, together"]}]}$json$::jsonb, $json${"dc":6,"wDef":22,"wAtk":15,"fightReward":0}$json$::jsonb)
